namespace GeetaStudio.Api;

public static class RegistryPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>Characters, casting and story review</title>
<style>body{font:17px system-ui;max-width:1100px;margin:2rem auto;padding:1rem;color:#234}section,article{border:1px solid #ccd;padding:1rem;margin:1rem 0}label{display:block;margin:.5rem 0}input,select,textarea,button{font:inherit;padding:.4rem;max-width:95%}textarea{width:95%;min-height:5rem}pre{white-space:pre-wrap}button{margin:.3rem}</style>
<h1>Characters, casting and story review</h1><p>Original fictional dialogue is not scripture or history. Draft characters can be deliberately selected. Release requires human reviews, current source permissions and approved media. No media production or publishing happens here.</p>
<label>Tenant <select id="tenant"></select></label><label>Universe <select id="universe"></select></label><button id="load">Load registry</button><button id="defaults">Propose universe defaults</button><p id="status" role="status" aria-live="polite"></p>
<section><h2>Universe bible</h2><div id="bibles"></div><details><summary>Edit bible as a new version</summary><label>Existing bible <select id="bibleEdit"></select></label><div id="bibleFields"></div><button id="bibleSave">Save new review draft</button></details></section>
<section><h2>Character registry</h2><div id="characters"></div>
<details open><summary>Register, edit or duplicate a character</summary><label>Profile to edit or copy <select id="characterEdit"></select></label><button id="new">New guest</button><button id="copy">Duplicate as a distinct identity</button><label>Registry key <input id="key"></label><label>Persistence <select id="scope"><option>Guest</option><option>EpisodeOnly</option><option>Recurring</option><option>Core</option></select></label><div id="characterFields"></div><button id="save">Save profile draft</button></details></section>
<section><h2>Presentations and relationships</h2><p>Presentation styles share the same reviewed identity/voice anchors. A guide without approved visual/voice assets is suitable for text drafts only.</p><div id="presentations"></div><div id="relationships"></div>
<label>Character <select id="presentationCharacter"></select></label><label>Presentation style <input id="presentationStyle" value="Default"></label><label>Visual asset reference (optional) <input id="visual"></label><label>Voice asset reference (optional) <input id="voice"></label><label>Estimated cost <input id="cost" type="number" value="0"></label><button id="presentationSave">Propose presentation</button>
<label>Relationship from <select id="relFrom"></select></label><label>To <select id="relTo"></select></label><label>Relationship key <input id="relKey"></label><label>Kind <input id="relKind"></label><label>Continuity <input id="relContinuity"></label><label>Arc state <input id="relArc"></label><button id="relSave">Propose relationship</button></section>
<section><h2>Episode and situational cast</h2><label>Episode <select id="episode"></select></label><label>New episode key <input id="episodeKey"></label><button id="episodeSave">Register episode identity</button><label>Approved bible <select id="bible"></select></label><label>Audience <select id="audience"></select></label><label>Locale <select id="locale"></select></label>
<label>Situation tags <input id="situations" value="collaboration"></label><label>Required skills <input id="skills"></label><label>Learning objectives <input id="objectives" value="understand-context"></label><label>Roles <input id="roles" value="Lead"></label><label>Continuity tags <input id="continuity" value="original-timeline"></label><label>Subject tags <input id="subjects"></label><label>Maximum speakers <input id="maxCast" type="number" value="4"></label><label>Maximum estimated cost <input id="maxCost" type="number" value="0"></label><label>Currency <input id="currency" value="INR"></label><label>Require approved media <input id="media" type="checkbox"></label>
<label>Deliberate character choice (optional) <select id="pin"></select></label><label>Pinned role <input id="pinRole" value="Lead"></label><button id="cast">Find eligible cast</button><div id="candidates"></div></section>
<section><h2>Reviewed story beats</h2><p>Choose a cast first. Each speaking character must be registered; traits come from selected profiles. Lead beats must include a decision. Forbidden humor cannot be overridden.</p><label>Humor <select id="humor"><option>None</option><option>Gentle</option><option>Satire</option></select></label><label>References real people <input id="real" type="checkbox"></label><label>References current events <input id="events" type="checkbox"></label>
<label>Relationship revisions to pin <select id="storyRelationships" multiple></select></label><label>Lesson variant (optional) <input id="lesson"></label><label>Content revision (optional; required for release) <input id="content"></label><div id="beats"></div><button id="compose">Save new episode revision</button><div id="stories"></div></section>
<script>
const $=id=>document.getElementById(id),op=()=>crypto.randomUUID(),parts=id=>$(id).value.split(',').map(x=>x.trim()).filter(Boolean);
let profiles=[],bibles=[],presentations=[],relationships=[],episodes=[],catalog=null,edit=null,editingCharacter=null,distinctFrom=null,bibleRules=null,plan=null,beats=[];
const base=()=>'/api/v1/registry/tenants/'+$('tenant').value+'/universes/'+$('universe').value;
async function call(path,data){const r=await fetch(path,{credentials:'same-origin',method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},body:data===undefined?undefined:JSON.stringify(data)});const t=await r.text();const v=t?JSON.parse(t):null;if(!r.ok)throw Error(v?.error||'Request failed');return v;}
async function act(fn){try{$('status').textContent='Working…';await fn();$('status').textContent='Done.';}catch(e){$('status').textContent=e.message;}}
function select(id,rows,label,empty=false){const el=$(id),old=el.value;el.replaceChildren();if(empty){const opt=document.createElement('option');opt.value='';opt.textContent='No pinned choice';el.append(opt);}for(const x of rows){const opt=document.createElement('option');opt.value=x.id;opt.textContent=label(x);el.append(opt);}if(rows.some(x=>x.id===old))el.value=old;}
function para(parent,title,value){const p=document.createElement('p');const s=document.createElement('strong');s.textContent=title+': ';p.append(s,document.createTextNode(value||'—'));parent.append(p);}
function fields(obj,parent){parent.replaceChildren();for(const [key,value] of Object.entries(obj)){const label=document.createElement('label');label.append(document.createTextNode(key.replace(/([A-Z])/g,' $1')+' '));
if(Array.isArray(value)&&value.some(x=>x&&typeof x==='object')){for(const row of value){const group=document.createElement('fieldset');fields(row,group);label.append(group);}parent.append(label);continue;}
if((key==='audienceIds'||key==='audienceId')&&catalog){const choices=document.createElement('select');choices.multiple=key==='audienceIds';for(const a of catalog.manifest.audiences){const option=document.createElement('option');option.value=a.id;option.textContent=a.name;option.selected=Array.isArray(value)?value.includes(a.id):value===a.id;choices.append(option);}choices.onchange=()=>obj[key]=choices.multiple?[...choices.selectedOptions].map(x=>x.value):choices.value;label.append(choices);parent.append(label);continue;}
const input=document.createElement(typeof value==='string'&&value.length>150?'textarea':'input');if(typeof value==='boolean'){input.type='checkbox';input.checked=value;input.onchange=()=>obj[key]=input.checked;}else{input.value=Array.isArray(value)?value.join(', '):value??'';input.onchange=()=>obj[key]=Array.isArray(value)?input.value.split(',').map(x=>x.trim()).filter(Boolean):typeof value==='number'?Number(input.value):input.value||null;}label.append(input);parent.append(label);}}
function review(v){const b=document.createElement('button');b.textContent='Record review';b.onclick=()=>act(async()=>{const evidence=prompt('manual: human review reference, or fixture: explicitly test-only');if(!evidence)return;const escalation=prompt('For satire/real-person/current-event stories, provide a separate escalation reference; otherwise leave blank.');await call(base()+'/revisions/'+v.id+'/review',{operationId:op(),expectedRowVersion:v.rowVersion,approve:confirm('Approve? Cancel records rejection.'),evidenceReference:evidence,escalationEvidence:escalation||null});await load();});return b;}
function editCharacter(){const c=profiles.find(c=>c.characterId===$('characterEdit').value);if(!c)return;editingCharacter=c;distinctFrom=null;edit=structuredClone(c.profile.rules);$('key').value=c.key;$('scope').value=c.persistenceScope;fields(edit,$('characterFields'));}
function fresh(){editingCharacter=null;distinctFrom=null;edit={name:'',lifeStage:'',biography:'',fictionalStatus:'Fictional',traits:[''],goals:[''],flaws:[],speechStyle:'',roles:['Lead'],situationTags:['collaboration'],skillTags:[],learningObjectives:['understand-context'],audienceIds:[$('audience').value],locales:[$('locale').value||'en-IN'],continuityTags:['original-timeline'],arcState:'Proposed',pronunciationGuide:'Review required',visualAnchor:'',voiceAnchor:'',aliases:[],episodeId:null,identityEvidence:[],identityPermissionReference:null,storyDevice:'OrdinaryFiction'};$('key').value='';$('scope').value='Guest';fields(edit,$('characterFields'));}
function brief(){return{bibleRevisionId:$('bible').value,episodeId:$('episode').value,audienceId:$('audience').value,locale:$('locale').value,situationTags:parts('situations'),skillTags:parts('skills'),learningObjectives:parts('objectives'),roles:parts('roles'),continuityTags:parts('continuity'),subjectTags:parts('subjects'),budget:{maxSpeakingCharacters:Number($('maxCast').value),maxEstimatedCost:Number($('maxCost').value),currency:$('currency').value,requireMedia:$('media').checked},pinnedChoices:$('pin').value?[{characterId:$('pin').value,role:$('pinRole').value,presentationRevisionId:null}]:[],mode:'Draft'};}
async function load(){
[bibles,profiles,presentations,relationships,episodes,catalog]=await Promise.all([call(base()+'/bibles'),call(base()+'/characters'),call(base()+'/presentations'),call(base()+'/relationships'),call(base()+'/episodes'),call('/api/v1/core/tenants/'+$('tenant').value+'/universes/'+$('universe').value+'/catalog')]);plan=null;beats=[];$('beats').replaceChildren();$('candidates').replaceChildren();
select('audience',catalog.manifest.audiences,x=>x.name);select('locale',catalog.locales.map(id=>({id})),x=>x.id);
for(const id of ['characterEdit','presentationCharacter','relFrom','relTo'])select(id,profiles.map(c=>({id:c.characterId,c})),x=>x.c.profile.rules.name);
select('pin',profiles.map(c=>({id:c.characterId,c})),x=>x.c.profile.rules.name+' / '+x.c.status,true);select('episode',episodes,x=>x.key+' v'+x.currentVersion);select('bible',bibles.filter(x=>x.reviewStatus==='Approved'),x=>x.rules.title+' v'+x.version);select('bibleEdit',bibles,x=>x.rules.title+' v'+x.version);select('storyRelationships',relationships.filter(x=>x.reviewStatus==='Approved'),x=>x.key+' v'+x.version);
for(const [id,rows] of [['bibles',bibles],['presentations',presentations],['relationships',relationships]]){const el=$(id);el.replaceChildren();for(const v of rows){const a=document.createElement('article');para(a,v.key,'version '+v.version+' / '+v.reviewStatus);for(const [key,value] of Object.entries(v.rules)){if(value==null)continue;para(a,key.replace(/([A-Z])/g,' '+ ''),Array.isArray(value)?value.map(x=>typeof x==='object'?Object.entries(x).map(([k,v])=>k+': '+v).join(' / '):x).join('; '):String(value));}if(v.reviewStatus==='Draft')a.append(review(v));el.append(a);}}
$('characters').replaceChildren();for(const c of profiles){const a=document.createElement('article');para(a,c.profile.rules.name,c.profile.rules.lifeStage+' / '+c.persistenceScope+' / '+c.status+' / '+c.profile.reviewStatus);para(a,'Traits and goals',c.profile.rules.traits.join(', ')+' / '+c.profile.rules.goals.join(', '));para(a,'Situations and roles',c.profile.rules.situationTags.join(', ')+' / '+c.profile.rules.roles.join(', '));para(a,'Arc and guides',c.profile.rules.arcState+' / '+c.profile.rules.pronunciationGuide);if(c.profile.reviewStatus==='Draft')a.append(review(c.profile));for(const action of ['Activate','Retire','PromoteGuest']){const b=document.createElement('button');b.textContent=action;b.onclick=()=>act(async()=>{const evidence=prompt('Explicit manual: review reference (fixture: for tests only)');if(!evidence)return;await call(base()+'/characters/'+c.characterId+'/lifecycle',{operationId:op(),expectedRowVersion:c.rowVersion,action,evidenceReference:evidence});await load();});a.append(b);}$('characters').append(a);}
$('stories').replaceChildren();for(const v of await call(base()+'/stories')){const a=document.createElement('article');para(a,v.key,'revision '+v.version+' / '+v.reviewStatus);para(a,'Label',v.rules.fictionLabel);para(a,'Satire',v.rules.satireLabel);para(a,'Universe',v.rules.bible.rules.title);para(a,'Cast',v.rules.cast.map(c=>c.character.profile.rules.name+' / '+c.character.profile.rules.lifeStage+' / '+c.role+' / profile v'+c.character.profile.version).join('; '));for(const b of v.rules.beats)para(a,b.label,b.text);if(v.reviewStatus==='Draft')a.append(review(v));const exportButton=document.createElement('button');exportButton.textContent='Check qualified export';exportButton.onclick=()=>act(async()=>{await call(base()+'/stories/'+v.id+'/export');alert('Export gate passed. No publication performed.');});a.append(exportButton);$('stories').append(a);}
editCharacter();$('bibleEdit').onchange();
}
$('characterEdit').onchange=editCharacter;$('new').onclick=fresh;$('copy').onclick=()=>{const c=editingCharacter;if(!c)return;distinctFrom=c.characterId;editingCharacter=null;edit=structuredClone(c.profile.rules);edit.name+=' distinct version';edit.aliases=[];edit.visualAnchor+='-distinct';edit.voiceAnchor+='-distinct';$('key').value+='-distinct';$('scope').value='Guest';fields(edit,$('characterFields'));};
$('save').onclick=()=>act(async()=>{if(!edit)throw Error('Create/edit a profile first.');await call(base()+'/characters',{operationId:op(),key:$('key').value,persistenceScope:$('scope').value,rules:edit,characterId:editingCharacter?.characterId||null,expectedRowVersion:editingCharacter?.rowVersion||null,distinctFromCharacterId:distinctFrom});await load();});
$('bibleEdit').onchange=()=>{const v=bibles.find(v=>v.id===$('bibleEdit').value);if(v){bibleRules=structuredClone(v.rules);fields(bibleRules,$('bibleFields'));}};
$('bibleSave').onclick=()=>act(async()=>{const v=bibles.find(v=>v.id===$('bibleEdit').value);await call(base()+'/bibles',{operationId:op(),key:v.key,version:Math.max(...bibles.filter(x=>x.key===v.key).map(x=>x.version))+1,rules:bibleRules});await load();});
$('presentationSave').onclick=()=>act(async()=>{const c=profiles.find(c=>c.characterId===$('presentationCharacter').value);const key=c.key+'-'+$('presentationStyle').value;await call(base()+'/presentations',{operationId:op(),key,version:Math.max(0,...presentations.filter(p=>p.key===key).map(p=>p.version))+1,rules:{profileRevisionId:c.profile.id,audienceId:$('audience').value,locale:$('locale').value,style:$('presentationStyle').value,visualAnchor:c.profile.rules.visualAnchor,voiceAnchor:c.profile.rules.voiceAnchor,pronunciationGuide:c.profile.rules.pronunciationGuide,visualAssetReferenceId:$('visual').value||null,voiceAssetReferenceId:$('voice').value||null,estimatedCost:Number($('cost').value),currency:$('currency').value}});await load();});
$('relSave').onclick=()=>act(async()=>{const key=$('relKey').value;await call(base()+'/relationships',{operationId:op(),key,version:Math.max(0,...relationships.filter(p=>p.key===key).map(p=>p.version))+1,rules:{fromCharacterId:$('relFrom').value,toCharacterId:$('relTo').value,kind:$('relKind').value,continuity:$('relContinuity').value,arcState:$('relArc').value}});await load();});
$('episodeSave').onclick=()=>act(async()=>{await call(base()+'/episodes',{operationId:op(),key:$('episodeKey').value});await load();});
$('cast').onclick=()=>act(async()=>{plan=await call(base()+'/cast',brief());$('candidates').replaceChildren();for(const c of plan.candidates)para($('candidates'),c.character.profile.rules.name+' / '+c.role,c.reasons.join('; '));for(const p of plan.guestProposals)para($('candidates'),'Unregistered guest proposal',p.name+' — register a reviewed life stage/profile before use.');
beats=plan.selected.map(c=>({speakerCharacterId:c.character.characterId,label:'FictionalDialogue',text:'',traitClaims:[],humorTreatments:[],makesChoice:c.role==='Lead',claimsCanonicalAuthority:false}));$('beats').replaceChildren();for(let i=0;i<beats.length;i++){const b=document.createElement('fieldset');const l=document.createElement('legend');l.textContent=plan.selected[i].character.profile.rules.name+' / '+plan.selected[i].role;b.append(l);const body=document.createElement('div');fields(beats[i],body);b.append(body);$('beats').append(b);}});
$('compose').onclick=()=>act(async()=>{if(!plan)throw Error('Find and review a cast first.');const e=episodes.find(e=>e.id===$('episode').value);await call(base()+'/stories',{operationId:op(),expectedRowVersion:e.rowVersion,brief:brief(),humorStyle:$('humor').value,beats,relationshipRevisionIds:[...$('storyRelationships').selectedOptions].map(x=>x.value),referencesRealPeople:$('real').checked,referencesCurrentEvents:$('events').checked,lessonVariantId:$('lesson').value||null,contentRevisionId:$('content').value||null});await load();});
$('load').onclick=()=>act(load);$('defaults').onclick=()=>act(async()=>{await call(base()+'/proposals',{});await load();});
async function universes(){select('universe',await call('/api/v1/core/tenants/'+$('tenant').value+'/universes'),x=>x.name);}
$('tenant').onchange=()=>act(universes);act(async()=>{select('tenant',await call('/api/v1/core/tenants'),x=>x.name);await universes();});
</script></html>
""";
}
